css:
body{font-family:"Inter Variable",Inter,"SF Pro Display",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;font-feature-settings:"cv01","ss03";}
.chat-markdown code,.chat-markdown-codeblock{font-family:"Berkeley Mono",ui-monospace,"SF Mono",Menlo,monospace;}
[data-thread-item]{border-radius:6px!important;}
[data-slot="button"],[data-slot="input"],[data-slot="select-trigger"]{border-radius:6px!important;}
[data-slot="button"]{font-weight:500;}
[data-slot="composer-host"]{border-radius:10px!important;border:1px solid var(--border)!important;box-shadow:0 4px 24px rgba(0,0,0,.08)!important;}
[data-user-message-bubble]{border-radius:8px!important;}
.chat-markdown-codeblock{border-radius:6px!important;border:1px solid var(--border);}
.dark [data-slot="dialog-popup"],.dark [data-slot="popover-popup"],.dark [data-slot="menu-popup"]{border-radius:10px!important;border:1px solid #2A2C30!important;box-shadow:0 7px 32px rgba(0,0,0,.35)!important;}
:root:not(.dark) [data-slot="dialog-popup"],:root:not(.dark) [data-slot="popover-popup"],:root:not(.dark) [data-slot="menu-popup"]{border-radius:10px!important;border:1px solid var(--border)!important;box-shadow:0 7px 32px rgba(0,0,0,.1)!important;}
[data-slot="tooltip-popup"]{border-radius:6px!important;}
svg.lucide{stroke-width:1.75;}
button.bg-message-action:disabled{background:color-mix(in srgb,var(--foreground) 10%,transparent)!important;color:var(--muted-foreground)!important;opacity:1!important;}
.dark [data-slot="switch"][data-unchecked]{background:#2A2C30!important;box-shadow:none!important;}
:root:not(.dark) [data-slot="switch"][data-unchecked]{background:#D7D8DE!important;box-shadow:none!important;}
[data-slot="switch"][data-unchecked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
[data-slot="switch"][data-checked]{background:#5E6AD2!important;box-shadow:none!important;}
[data-slot="switch"][data-checked] [data-slot="switch-thumb"]{background:#FFFFFF!important;}
::-webkit-scrollbar{width:8px;height:8px;}
::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--foreground) 14%,transparent);border-radius:999px;border:2px solid transparent;background-clip:padding-box;}
::selection{background:rgba(94,106,210,.35);}
